<template>
	<!-- :style="{ paddingTop: safeAreaInsets.top + 'px',paddingBottom: safeAreaInsets.bottom + 'px' }" -->
	<view class="container">
		<uv-navbar leftText="返回" :fixed="false" title="新的植物" :safeAreaInsetTop="true">
			<template v-slot:left>
				<view class="uv-nav-slot">
					<!-- <uv-icon name="arrow-left" size="19"></uv-icon> -->
					<uv-button size="mini" text="取消" type="info" :plain="true" @click="back"></uv-button>
					<uv-line direction="column" :hairline="false" length="16" margin="0 8px"></uv-line>
					<uv-button size="mini" text="保存" type="success" :plain="true" @click="addNew"></uv-button>
					<!-- <uv-icon name="home" size="20"></uv-icon> -->
				</view>
			</template>
		</uv-navbar>
		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<!-- <text class="uni-body">这是一个基础卡片示例，内容较少，此示例展示了一个没有任何属性不带阴影的卡片。</text> -->

			<uni-row class="demo-uni-row" :width="nvueWidth">
				<uni-col :span="7">
					<uv-upload :fileList="fileList1" name="1" :maxCount="1" multiple :previewFullImage="true"
						:maxSize="1000000" @afterRead="afterRead" @delete="deletePic"></uv-upload>
				</uni-col>
				<uni-col :span="17">
					<view style="padding-top: 60rpx;">
						<uv-input placeholder="请输入植物昵称" border="bottom" @input="onTNickName"></uv-input>
					</view>
				</uni-col>
			</uni-row>
		</uni-card>

		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<view>
				<uv-text type="success" text="品种"></uv-text>
				<uv-input placeholder="请输入植物品种" @input="onTVariety"></uv-input>
			</view>
			<!-- <view>
				<uv-text type="success" text="性别"></uv-text>
				<uv-radio-group v-model="radiovalue" placement="row">
					<uv-radio name="公" activeColor="green" label="公"></uv-radio>
					<uv-radio name="母" activeColor="green" label="母"></uv-radio>
					<uv-radio name="不详" activeColor="green" label="不详"></uv-radio>
				</uv-radio-group>
			</view> -->
			<view>
				<uv-text type="success" text="尺寸"></uv-text>
				<uv-input placeholder="请输入植物尺寸,单位cm" type="digit" @input="onTSize"></uv-input>
			</view>
			<!-- <view>
				<uv-text type="success" text="克重"></uv-text>
				<uv-input placeholder="请输入爱龟克重,单位g" type="digit" @input="onTWeight"></uv-input>
			</view> -->
		</uni-card>

		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<view>
				<uv-text type="success" text="标签"></uv-text>
				<uv-list>
					<uv-list-item :title="TTag==''?'添加标签': TTag" clickable link @click="popTag"></uv-list-item>
				</uv-list>
			</view>
			<view>
				<uv-text type="success" text="到家时间"></uv-text>
				<uv-list>
					<uv-list-item :title="getTime(dateValue)" clickable link @click="dateOpen"></uv-list-item>
				</uv-list>
			</view>
		</uni-card>


		<!-- 标签弹出页面 -->
		<uv-picker ref="picker" :columns="tagList" @confirm="tagConfirm" confirmColor="#5AC725"></uv-picker>

		<!-- 时间选择 -->
		<uv-datetime-picker ref="datetimePicker" v-model="dateValue" mode="date" confirmColor="#5AC725"
			@confirm="dateConfirm"></uv-datetime-picker>


	</view>
</template>

<script>
	export default {
		data() {
			return {
				fileList1: [],
				openId: "",
				safeAreaInsets: "",
				radiovalue: '不详',
				type: 'center',
				showTag: false,
				tagList: [[]],
				dateValue: Number(new Date()),
				TNickName: '',
				TVariety: '',
				TSize: 0,
				TWeight: 0,
				TTag: ''
			}
		},
		methods: {
			popTag() {
				this.$refs.picker.open();
			},
			tagConfirm(e) {
				this.TTag = e.value[0]
			},
			dateOpen() {
				this.$refs.datetimePicker.open();
			},
			dateConfirm(e) {
				this.dateValue = e.value
			},
			onTNickName(e) {
				this.TNickName = e
			},
			onTVariety(e) {
				this.TVariety = e
			},
			onTSize(e) {
				this.TSize = e
			},
			onTWeight(e) {
				this.TWeight = e
			},
			// 删除图片
			deletePic(event) {
				this[`fileList${event.name}`].splice(event.index, 1)
			},
			getTime(timestamp, format = 'YYYY年MM月DD日') {
			  const date = new Date(timestamp);
			  const map = {
			    'YYYY': date.getFullYear(),
			    'MM': (date.getMonth() + 1).toString().padStart(2, '0'),
			    'DD': date.getDate().toString().padStart(2, '0')
			  };
			  return format.replace(/YYYY|MM|DD/g, matched => map[matched]);
			},
			// 新增图片
			async afterRead(event) {
				// 当设置 multiple 为 true 时, file 为数组格式，否则为对象格式
				let lists = [].concat(event.file)
				let fileListLen = this[`fileList${event.name}`].length
				lists.map((item) => {
					this[`fileList${event.name}`].push({
						...item,
						status: 'uploading',
						message: '上传中'
					})
				})
				for (let i = 0; i < lists.length; i++) {
					let item = this[`fileList${event.name}`][fileListLen]
					this[`fileList${event.name}`].splice(fileListLen, 1, Object.assign(item, {
						status: 'success',
						message: '',
						url: lists[0].url
					}))
					fileListLen++
				}
			},
			addNew() {
				console.log(this.fileList1)
				let fileID = ''
				if (this.fileList1.length > 0 && this.openId != '' && this.TNickName != '') {
					wx.cloud.uploadFile({
							cloudPath: this.openId + "/" + Date.now() + ".jpg", // 上传至云端的路径
							filePath: this.fileList1[0].url, // 小程序临时文件路径，需结合小程序相关 API 获取
						})
						.then((res) => {
							// 返回文件 ID
							console.log(res);
							fileID = res.fileID
							wx.cloud.callFunction({
								name: 'savePrintInfo',
								data: {
									flag: 0,
									openId: this.openId,
									// weight: this.TWeight,
									length: this.TSize,
									name: this.TNickName,
									variety:this.TVariety,
									// sex: this.radiovalue,
									classification: this.TTag,
									feedCycle: null,
									content: null,
									birthday: this.dateValue,
									photo: fileID,

								},
								complete: res => {
									console.log('callFunction test result: ', res)
									uni.redirectTo({
										url:'/pages/index/index'
									})
								},
								fail: res1 =>{
									console.log(res1)
								}
							})
						});
				} else {
					uni.showToast({
						title: "请上传图片或者填写昵称"
					})
				}
			},
			getTagList() {
				wx.cloud.callFunction({
					name: 'getClass',
					data: {
						"openId": this.openId,
					},
					complete: res => {
						console.log('callFunction test result: ', res)
						let data = res.result.data
						if (data.length > 0) {
							data.map((item, index) => {
								this.tagList[0].push(item.title)
							})
			
						}
			
					}
				})
			},
			back(){
				uni.navigateBack()
			}
		},
		onLoad() {
			this.openId = this.$store.state.openId
			console.log(this.$store.state.openId)
			uni.getSystemInfo({
				success: (res) => {
					console.log(res.safeAreaInsets)
					this.safeAreaInsets = res.safeAreaInsets
				}
			})
			// this.getTagList()
		},
		mounted() {

		}
	}
</script>

